SELECT COUNT(*) as total_records, AVG(consumption) as avg_consumption, PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY consumption) as median_consumption, PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY consumption) as p25, PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY consumption) as p75, MIN(consumption) as min_consumption, MAX(consumption) as max_consumption, COUNT(DISTINCT consumption) as distinct_consumptions, SUM(CASE WHEN consumption IS NULL THEN 1 ELSE 0 END) as null_count FROM yearmonth WHERE consumption IS NOT NULL;
